describe('createServer sessionStore wiring', () => {
  it('forwards sessionStore to the message handler so list_sessions queries listFor', async () => {
    const calls: Array<{userId: string | number; options?: unknown}> = [];
    const sessionStore = {
      create: (sessionId: string, userId: string | number): ChatSession => ({sessionId, userId, entries: []}),
      delete: () => true,
      listFor: (userId: string | number, options?: unknown) => {
        calls.push({userId, options});
        return [];
      },
    } as unknown as SessionStore;

    const hal = createServer({
      app: (() => undefined) as unknown as Express,
      wsAuth: jest.fn() as unknown as WsAuthenticator,
      sessionStore,
      orchestrator: {} as ChatOrchestrator,
    });

    const listeners: Record<string, (data?: unknown) => void> = {};
    const ws = {
      userId: 'u1',
      isAlive: true,
      send: () => undefined,
      on: (event: string, listener: (data?: unknown) => void) => {
        listeners[event] = listener;
      },
      pause: () => undefined,
      resume: () => undefined,
      close: () => undefined,
    } as unknown as ExtWebSocket;

    hal.wss.emit('connection', ws);
    await settle();
    listeners.message?.(JSON.stringify({type: 'list_sessions', limit: 5}));
    await settle();
    hal.wss.emit('close');

    expect(calls).toEqual([{userId: 'u1', options: {limit: 5, before: undefined}}]);
  });
});

